"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["15448"],{77574(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.corte_em_area_repetido","status":422,"titulo":"A mesma \xe1rea tem mais de um corte"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.corte_em_area_repetido","requisitos":[],"oQueAconteceu":["A lista `regrasEliminacao` da classifica\xe7\xe3o traz a elimina\xe7\xe3o por corte em \xe1rea\\n(`ELIMINACAO_CORTE_EM_AREA`) mais de uma vez com o mesmo `areaCodigo`. O primeiro corte vale; cada\\nrepeti\xe7\xe3o \xe9 recusada no pr\xf3prio item, no campo `regrasEliminacao[i]`, e acumula no array\\n`errors[]` com as demais viola\xe7\xf5es da requisi\xe7\xe3o. O c\xf3digo da \xe1rea \xe9 comparado exatamente\\ncomo foi enviado.","Com dois m\xednimos para a mesma \xe1rea, o menor n\xe3o eliminaria ningu\xe9m que o maior j\xe1 n\xe3o\\neliminasse. \xc1reas diferentes podem, cada uma, ter o seu corte; o que n\xe3o se repete \xe9 o corte\\npara a mesma \xe1rea.","A confer\xeancia s\xf3 vale para classifica\xe7\xe3o com c\xe1lculo local. Na classifica\xe7\xe3o importada, que\\nn\xe3o admite regra de elimina\xe7\xe3o nenhuma, a recusa \xe9 a da lista inteira, em\\n[`eliminacao_indevida`](/erros/uniplus.selecao.configuracao_classificacao.eliminacao_indevida).\\nO item repetido \xe9 recusado s\xf3 por esta causa: a confer\xeancia de que a \xe1rea est\xe1 no quadro de\\npesos\\n([`corte_em_area_fora_do_quadro`](/erros/uniplus.selecao.configuracao_classificacao.corte_em_area_fora_do_quadro))\\nn\xe3o roda sobre ele.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o da classifica\xe7\xe3o, mantenha um s\xf3 corte para cada \xe1rea, com o m\xednimo que o edital\\nfixa, e remova as repeti\xe7\xf5es.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);